sp_widget.client_script:
function($scope, $http, $timeout, $uibModal, $sce) {

    $scope.modalData = {};

    $scope.openModal = function(node) {
        var usersHtml = node.users ? $sce.trustAsHtml(node.users) : '';

        $scope.modalData = {
            name: node.name,
            title: node.title,
            desc: node.desc,
            users: usersHtml,
            gestorTitular: node.gestorTitular || 'Não informado',
            gestorSub1: node.gestorSub1 || 'Não informado',
            gestorSub2: node.gestorSub2 || 'Não informado'
        };

        $scope.modalInstance = $uibModal.open({
            templateUrl: 'modalTemplate',
            scope: $scope
        });
    };

    $scope.closeModal = function() {
        if ($scope.modalInstance) {
            $scope.modalInstance.close();
            $scope.modalInstance = null;
        }
    };

    function loadScript(src) {
        return new Promise(function(resolve, reject) {
            var script = document.createElement('script');
            script.src = src;
            script.onload = resolve;
            script.onerror = reject;
            document.head.appendChild(script);
        });
    }

    function loadAllScripts() {
        var scripts = [
            'https://code.highcharts.com/highcharts.js',
            'https://code.highcharts.com/modules/sankey.js',
            'https://code.highcharts.com/modules/organization.js',
            'https://code.highcharts.com/modules/exporting.js',
            'https://code.highcharts.com/modules/accessibility.js'
        ];

        var promise = Promise.resolve();
        for (var i = 0; i < scripts.length; i++) {
            (function(src) {
                promise = promise.then(function() {
                    return loadScript(src);
                });
            })(scripts[i]);
        }
        return promise;
    }

    function initChart() {
        loadAllScripts().then(function() {

            Highcharts.setOptions({
                chart: {
                    style: {
                        fontFamily: 'Roboto Flex, sans-serif'
                    }
                }
            });

            Highcharts.chart('container', {
                chart: {
                    height: 800,
                    inverted: true,
                    events: {
                       render: function() {
                          var parents = document.querySelectorAll('.highcharts-label.highcharts-data-label.highcharts-data-label-color-undefined.highcharts-tracker');
                          parents.forEach(function(parent) {
                            var h4s = parent.querySelectorAll('h4');
                            h4s.forEach(function(h4) {
                              h4.style.display = 'none';
                            });

                            var ps = parent.querySelectorAll('p');
                            ps.forEach(function(p) {
                              p.style.fontSize = '18px';
                            });
                          });
                       }
                    }
                },
                title: {
                    text: null
                },
                series: [{
                    type: 'organization',
                    name: 'Organograma',
                    keys: ['from', 'to'],
                    data: $scope.data.links,
                    nodes: $scope.data.nodes,
                    colorByPoint: false,
                    color: '#293273',
                    borderColor: 'white',
                    nodeWidth: 100,
										borderRadius: 45,
                    dataLabels: {
                        color: 'white',
                        style: {
                            textOutline: 'none',
                            fontWeight: 'bold'
                        },
                        formatter: function() {
                            return this.point.title;
                        }
                    },  states: {
        inactive: {
            opacity: 0.5 // Aumente esse valor para deixar menos transparente
        }
    },
                    events: {
                        click: function(event) {
                            var node = event.point;
                            $scope.openModal({
                                name: node.name,
                                title: node.title,
                                desc: node.desc,
                                users: node.users,
                                gestorTitular: node.gestorTitular,
                                gestorSub1: node.gestorSub1,
                                gestorSub2: node.gestorSub2
                            });
                            $scope.$apply();
                        }
                    }
                }],
                tooltip: {
                    enabled: false
                },
                exporting: {
                    enabled: true,
                    allowHTML: true,
                    sourceWidth: 1000,
                    sourceHeight: 800,
                    buttons: {
                        contextButton: {
                            menuItems: ['printChart', 'viewFullscreen']
                        }
                    }
                }
            });

            // Cantos arredondados dos nós
            var rects = document.querySelectorAll('#container svg rect.highcharts-point');
            for (var j = 0; j < rects.length; j++) {
                rects[j].setAttribute('rx', '15');
                rects[j].setAttribute('ry', '15');
            }

        }).catch(function(e) {
            console.error('Erro ao carregar ou inicializar gráfico:', e);
        });
    }

    $timeout(function() {
        initChart();
    }, 1000);

}

sp_widget.css:
div, h3, h2, h1, h4 {
	 font-family: 'Roboto Flex', sans-serif;
}

sp_widget.link:
function link(scope, element, attrs, controller) {
angular.module('sn.$sp').directive('orgChart', function($compile) {
  return {
    scope: {
      node: '='
    },
    templateUrl: 'org-chart-template',
    link: function(scope, element) {
      $compile(element.contents())(scope);
    }
  };
});


}

sp_widget.script:
(function() {

    // Função para buscar usuários ativos de um departamento
    function getUsersByDepartment(deptSysId) {
        var users = [];
        var userGr = new GlideRecord('sys_user');
        userGr.addQuery('active', true);
        userGr.addQuery('department', deptSysId);
        userGr.query();
        while (userGr.next()) {
            //users.push(userGr.name.toString() + ' - ' + (userGr.title.toString() || 'Sem função'));
					users.push(userGr.name.toString());
        }
        return users;
    }

    // Função para buscar info do usuário (gestor) pelo sys_id
    function getUserInfo(userSysId) {
        if (!userSysId) return 'Não informado';
        var userGr = new GlideRecord('sys_user');
        if (userGr.get(userSysId)) {
          //  return userGr.name.toString() + ' - ' + (userGr.title.toString() || 'Sem função');
					return userGr.name.toString();
        }
        return 'Não encontrado';
    }

    var nodes = [];
    var links = [];

    function fetchChildren(parentSysId, level) {
        var gr = new GlideRecord('cmn_department');
        gr.addQuery('u_nome_unidade_superior', parentSysId);
        gr.query();

        while (gr.next()) {
            var childSysId = gr.sys_id.toString();

            var users = getUsersByDepartment(childSysId);

            var gestorTitular = getUserInfo(gr.getValue('u_matricula_responsavel'));
            var gestorSub1 = getUserInfo(gr.getValue('u_matricula_substituto_1'));
            var gestorSub2 = getUserInfo(gr.getValue('u_matricula_substituto_2'));

            var color = '#6BB7F0'; // Azul escuro para netos e além
            if (level === 0) color = '#4A75B1'; // Cinza para o pai (root)
            else if (level === 1) color = '#4A75B1'; // Azul claro para os filhos diretos

            nodes.push({
                id: childSysId,
                title: gr.getValue('u_sigla_unidade') || '',
                name: gr.name.toString(),
                desc: gr.getValue('description') || '',
                users: users.join('<br>'),
                gestorTitular: gestorTitular,
                gestorSub1: gestorSub1,
                gestorSub2: gestorSub2,
                color: color
            });

            links.push([parentSysId, childSysId]);

            fetchChildren(childSysId, level + 1);
        }
    }

    var rootSysId = '22a5b94487030690947032a70cbb35ae'; // Seu root específico
    var root = new GlideRecord('cmn_department');
    if (root.get(rootSysId)) {
        var users = getUsersByDepartment(rootSysId);

        var gestorTitularRoot = getUserInfo(root.getValue('u_matricula_responsavel'));
        var gestorSub1Root = getUserInfo(root.getValue('u_matricula_substituto_1'));
        var gestorSub2Root = getUserInfo(root.getValue('u_matricula_substituto_2'));

        nodes.push({
            id: rootSysId,
            title: root.getValue('u_sigla_unidade') || '',
            name: root.name.toString(),
            desc: root.getValue('description') || '',
            users: users.join('<br>'),
            gestorTitular: gestorTitularRoot,
            gestorSub1: gestorSub1Root,
            gestorSub2: gestorSub2Root,
            color: '#E66734'
        });
    }

    fetchChildren(rootSysId, 1);

    data.links = links;
    data.nodes = nodes;

})();
